let text = Buffer.isBuffer(msg.payload)
    ? msg.payload.toString("utf8")
    : String(msg.payload);

// 2. Filter-Logik
// Erkennt Format A: "... for server ball-b-cs.cortex-media.de PULL_ACK ..."
// Erkennt Format B: "INFO: [down] PULL_ACK received ..." (ohne "for server" Angabe)
const isMyServer = text.includes("ball-b-cs.cortex-media.de PULL_ACK");
const isGenericPullAck = text.includes("PULL_ACK") && !text.includes("for server");

if (isMyServer || isGenericPullAck) {
    msg.payload = text;

    // Visuelles Feedback am Knoten
    node.status({ fill: "green", shape: "ring", text: "PULL_ACK gefiltert" });
    return msg;
}

// Alles andere (andere Server oder andere Log-Typen wie JSON UP) verwerfen
return null;

// store last valid ACK timestamp
flow.set("lastPullAck", Date.now());

return msg;

// =====================================
// Konfiguration
// =====================================
const MAX_AGE_SECONDS = 31;
const last = flow.get("lastPullAck");
const now = Date.now();

// Falls noch nie ein ACK empfangen wurde
if (!last) {
    const unknownData = { status: "UNKNOWN", seconds_since_ack: null, last_seen: null };
    flow.set("gatewayStatus", unknownData); // Auch UNKNOWN speichern
    node.status({ fill: "grey", shape: "dot", text: "Warte auf erstes ACK..." });
    msg.payload = unknownData;
    return msg;
}

// =====================================
// Auswertung
// =====================================
const ageSeconds = (now - last) / 1000;
const isOnline = ageSeconds <= MAX_AGE_SECONDS;
const status = isOnline ? "ONLINE" : "OFFLINE";

// Das Objekt erstellen, das wir senden UND speichern wollen
const statusUpdate = {
    status: status,
    seconds_since_ack: Math.round(ageSeconds),
    last_seen: new Date(last).toISOString()
};

// =====================================
// Speichern & Feedback
// =====================================
flow.set("gatewayStatus", statusUpdate); // WICHTIG: Hier wird das Objekt für den HTTP-Knoten fixiert

node.status({
    fill: isOnline ? "green" : "red",
    shape: "dot",
    text: `${status} (vor ${Math.round(ageSeconds)}s)`
});

msg.payload = statusUpdate;
return msg;

// Get data from flow context
const data = flow.get("gatewayStatus") || { status: "UNKNOWN", seconds_since_ack: null, last_seen: null };

// Get the new LNS Stat info
const now = Date.now();
const lastStat = flow.get("lastStatReceived") || 0;
const secondsSinceStat = Math.round((now - lastStat) / 1000);

// Determine LNS Connection (True Online)
// We check if both the Network ACK and the LNS Stat are fresh (within 65 seconds)
const isLnsOnline = (lastStat > 0 && secondsSinceStat < 65);
const isNetworkOnline = (data.status === "ONLINE");

// Final Status Integration
if (isNetworkOnline && isLnsOnline) {
    msg.statusCode = 200;
    msg.payload = {
        status: "ONLINE",
        lns_connected: true,
        last_seen: data.last_seen,
        seconds_since_ack: data.seconds_since_ack,
        seconds_since_stat: secondsSinceStat
    };
} else {
    msg.statusCode = 503;
    msg.payload = {
        status: !isNetworkOnline ? data.status : "LNS_DISCONNECTED",
        lns_connected: isLnsOnline,
        seconds_since_ack: data.seconds_since_ack,
        seconds_since_stat: secondsSinceStat,
        last_seen: data.last_seen || "nie"
    };
}

return msg;

const ACK_INTERVAL_S = 10;   // Erwartetes Intervall
const GAP_THRESHOLD_S = 15;  // Ab wann loggen wir (z.B. 1.5x Intervall)
const MAX_GAPS = 50;

const now = Date.now();
const last = flow.get("lastPullAckBuffer");
let gaps = flow.get("ackGaps") || [];

if (last) {
    const gapS = (now - last) / 1000;

    if (gapS > GAP_THRESHOLD_S) {
        // DER FIX: Das Gap beginnt erst 10s NACH der letzten Nachricht
        // Damit bleibt die Zeit zwischen 'last' und 'last + 10s' im Chart grün.
        const gapStartTimestamp = last + (ACK_INTERVAL_S * 1000);

        const newGap = {
            start: new Date(gapStartTimestamp).toISOString(),
            end: new Date(now).toISOString(),
            duration_s: Math.round((now - gapStartTimestamp) / 1000)
        };

        // Nur eintragen, wenn das Gap eine positive Dauer hat
        if (newGap.duration_s > 0) {
            gaps.push(newGap);
        }

        // Ringpuffer & Bereinigung (älter als 24h)
        const oneDayAgo = now - (24 * 60 * 60 * 1000);
        gaps = gaps.filter(g => new Date(g.end).getTime() > oneDayAgo);

        if (gaps.length > MAX_GAPS) {
            gaps.shift();
        }

        flow.set("ackGaps", gaps);
    }
}

// Immer Zeitstempel aktualisieren
flow.set("lastPullAckBuffer", now);
return null;

const gaps = flow.get("ackGaps") || [];

msg.statusCode = 200;
msg.payload = {
    gateway: flow.get("gatewayId") || "unknown",
    threshold_s: 15,
    window: "last 24 hours (max 50 gaps)",
    generated_at: new Date().toISOString(),
    gaps: gaps
};

return msg;

// =====================================
// 1. DATEN VORBEREITEN
// =====================================
const gaps = flow.get("ackGaps") || [];
const hours = parseFloat(msg.payload.hours) || 1;
const now = new Date();
const windowStart = new Date(now.getTime() - hours * 60 * 60 * 1000);

const dataForChart = {
    gaps: gaps
};

// =====================================
