return msg;

// Zeitstempel abrufen
const now = Date.now();
const lastStat = flow.get("lastStatReceived") || 0;
const ageSeconds = (now - lastStat) / 1000;

// Logik: Grün wenn unter 31s, sonst Rot
const isOnline = (lastStat > 0 && ageSeconds <= 31);
const status = isOnline ? "STAT OK" : "STAT TIMEOUT";

// Node-Status setzen
node.status({
    fill: isOnline ? "green" : "red",
    shape: "dot",
    text: `${status} (vor ${Math.round(ageSeconds)}s)`
});

return msg;

// 1. Payload sicher als String behandeln
let text = Buffer.isBuffer(msg.payload)
    ? msg.payload.toString("utf8")
    : String(msg.payload);

// 2. Filter-Logik
// Erkennt Format A: "... for server ball-b-cs.cortex-media.de PUSH_ACK ..."
// Erkennt Format B: "INFO: [down] PUSH_ACK received ..." (ohne "for server" Angabe)
const isMyServer = text.includes("ball-b-cs.cortex-media.de PUSH_ACK");
const isGenericPushAck = text.includes("PUSH_ACK") && !text.includes("for server");

if (isMyServer || isGenericPushAck) {
    msg.payload = text;

    // Visuelles Feedback am Knoten
    node.status({ fill: "green", shape: "ring", text: "PUSH_ACK gefiltert" });
    return msg;
}

// Alles andere (andere Server oder andere Log-Typen wie JSON UP) verwerfen
return null;

// store last valid ACK timestamp
flow.set("lastPushAck", Date.now());

return msg;

// --- Flow metadata (explicit, simple) ---
const flowVersion = "1.4.0";
const flowDate = "2026-11-23";

// --- Persist flow metadata ---
global.set("flowVersion", flowVersion);
global.set("flowDate", flowDate);

return msg;

// --- read global state ---
const flowVersion = global.get("flowVersion") || "unknown";
const flowDate = global.get("flowDate") || "unknown";

// --- read uptime output ---
const uptimeRaw = String(msg.payload || "").trim();
const uptime = uptimeRaw ? uptimeRaw.replace(/\s+/g, " ") : "unknown";

// --- build compact meta string ---
const metaStringParts = [
    `flow=${flowVersion}@${flowDate}`,
    `uptime="${uptime}"`
];

msg.meta = metaStringParts.join(" | ");
global.set("gatewayMetaString", msg.meta);

return msg;

// === CONFIG ===
const MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24h
const MAX_COUNT = 500;                 // zusätzlicher Schutz

// === LOAD ===
let log = global.get("statusLog") || [];
let seq = global.get("nextSeq") || 1;

const now = Date.now();
const cutoff = now - MAX_AGE_MS;

// === ENTRY ===
const entry = {
    seq,
    ts: now,
    received_at: new Date(now).toISOString(),
    meta: global.get("gatewayMetaString") || null,
    payload: msg.payload
};

// append
log.push(entry);
seq++;

// === TRIM (wichtig!) ===
// nur von vorne löschen → sortiert nach Zeit
while (log.length && (log[0].ts < cutoff || log.length > MAX_COUNT)) {
    log.shift();
}

// === SAVE ===
global.set("statusLog", log);
global.set("nextSeq", seq);

return msg;

// === WHO IS READING (db monitor app) -> /driveby/health ===
const hdr = (msg.req && msg.req.headers) || {};
global.set("appPoll", {
    ts: Date.now(),
    client: (hdr["x-forwarded-for"] || (msg.req && msg.req.ip) || "").split(",")[0].trim() || null,
    agent: (hdr["user-agent"] || "").slice(0, 80) || null
});
global.set("appPollCount", (global.get("appPollCount") || 0) + 1);

// === CONFIG ===
const MAX_ITEMS = 30;

// === LOAD ===
const log = global.get("statusLog") || [];
const bootId = global.get("bootId");

// === QUERY ===
const sinceRaw = msg.req?.query?.since;
let since = Number(sinceRaw);
let hasSince = Number.isFinite(since);

// === STATE ===
const latestSeq = log.length ? log[log.length - 1].seq : 0;

// sanitize since
if (!hasSince || since < 0 || since > latestSeq) {
    hasSince = false;
}

// optional: boot reset
const clientBoot = msg.req?.query?.boot_id;
if (clientBoot && clientBoot !== bootId) {
    hasSince = false;
}

// === CORE LOGIC ===
let items;
let dropped = false;

if (!hasSince) {
    // erster Aufruf oder Reset
    items = log.slice(-MAX_ITEMS);

} else {
    const missing = latestSeq - since;

    if (missing <= 0) {
        // nichts Neues
        items = [];

    } else if (missing <= MAX_ITEMS) {
        // normaler Betrieb
        items = log.slice(-missing);

    } else {
        // zu viel verpasst → fallback
        items = log.slice(-MAX_ITEMS);
        dropped = true;
    }
}

// === RESPONSE ===
msg.statusCode = 200;
msg.headers = {
    "Content-Type": "application/json",
    "Cache-Control": "no-store"
};

msg.payload = {
    boot_id: bootId,
    latest_seq: latestSeq,
    count: items.length,
    dropped: dropped,
    items: items
};

// OPTIONAL (empfohlen!)
// msg.payload.state = global.get("currentState");

return msg;

if (!global.get("statusLog")) {
    global.set("statusLog", []);
}

if (typeof global.get("nextSeq") !== "number") {
    global.set("nextSeq", 1);
}

// Optional but recommended
if (!global.get("bootId")) {
    global.set("bootId", Date.now());
}

return null;

// MAC säubern
let mac = msg.payload.trim().toUpperCase();
// pro Anfrage in msg tragen (flow-Kontext war bei parallelen Anfragen ein Race -> MAC 00:00…)
msg.gw_mac = mac;
flow.set("last_mac", mac);
return msg;

const raw = msg.payload;

const lines = raw
    .split(/\r?\n/)
    .map(l => l.replace(/^→+/, "").trim());

let ssid = null;

for (const line of lines) {
    if (line.startsWith("ssid ")) {
        ssid = line.replace("ssid ", "").trim();
        break; // first SSID is enough
    }
}

msg.ssid = ssid;

msg.gw_ssid = ssid;
flow.set("ssid", ssid);

return msg;

msg.payload = {
    username: "admin",
    password: "{{gateway_login_password_enc}}" // set by GatewayChef at deploy, never in git
};
return msg;

const jwt = flow.get("ug65_jwt");

if (!jwt) {
    node.error("JWT missing – login not executed", msg);
    return null;
}

msg.headers = {
    "Authorization": "Bearer " + jwt
};

return msg;

const body = msg.payload;

if (!body || !body.gatewayEui) {
    node.error("Gateway EUI not found", body);
    return null;
}

msg.gateway = {
    eui: body.gatewayEui,
    id: body.gatewayId ?? null
};

return msg;

// JWT aus Login-Response speichern
flow.set("ug65_jwt", msg.payload.jwt);

// optional: Ablaufzeit merken (für spätere Erneuerung)
msg.jwt = msg.payload.jwt;
return msg;

// 1. Daten abrufen
let rawIfconfig = msg.payload || "";
let rawMac = msg.gw_mac || flow.get("last_mac") || "00:00:00:00:00:00";
let ssid = msg.gw_ssid || flow.get("ssid") || "UNKNOWN";

// Fallback, falls ifconfig nicht lieferbar
if (rawIfconfig.includes("NO_IFCONFIG")) {
    rawIfconfig = "";
}

// 2. Interfaces aus ifconfig parsen
const lines = rawIfconfig.split("\n");
const interfaces = {};
let current = null;

for (let line of lines) {
    // Neues Interface: "eth0      Link encap:Ethernet..." oder "wg0       Link encap:UNSPEC..."
    const mIf = line.match(/^([a-zA-Z0-9]+)\s+Link encap:/);
    if (mIf) {
        current = mIf[1];
        interfaces[current] = {
            up: false,
            ip: null
        };
        continue;
    }
    if (!current) continue;

    // UP/RUNNING erkennen
    if (line.includes("UP") || line.includes("RUNNING")) {
        interfaces[current].up = true;
    }

    // IPv4: BusyBox-Format "inet addr:172.30.0.117"
    const mIp = line.match(/inet addr:([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)/);
    if (mIp) {
        interfaces[current].ip = mIp[1];
    }
}

// 3. VPN-IP aus wg0 bestimmen (wie bisher, nur aus parsed Interfaces)
let vpnIp = (interfaces.wg0 && interfaces.wg0.ip) ? interfaces.wg0.ip : "0.0.0.0";

// 3b. Primäre Interfaces markieren (für Frontend/Filter)
const primaryIfNames = ["eth0", "wg0", "wlan0", "ppp0", "ppp1", "wwan0"];
Object.keys(interfaces).forEach(name => {
    interfaces[name].primary = primaryIfNames.includes(name);
});

// 3c. Optional: Cellular-Status ableiten (z.B. ppp0/wwan0)
let cellularOnline = false;
["ppp0", "ppp1", "wwan0"].forEach(name => {
    if (interfaces[name] && interfaces[name].up && interfaces[name].ip) {
        cellularOnline = true;
    }
});

// 4. EUI berechnen (wie vorher)
let cleanMac = rawMac.replace(/:/g, "").toUpperCase();
let eui = "0000000000000000";
if (cleanMac.length === 12) {
    eui = cleanMac.substring(0, 6) + "FFFE" + cleanMac.substring(6);
}

// 5. Antwort-Objekt bauen (gleicher Stil wie dein Original, nur erweitert)
msg.payload = {
    status: (vpnIp === "0.0.0.0" || vpnIp === "") ? "offline" : "online",
    device: {
        mac: rawMac,
        eui: eui,
        ssid: ssid,
        vpn_ip: (vpnIp === "0.0.0.0" || vpnIp === "") ? "not_configured" : vpnIp,
        interfaces: interfaces,
        cellular_online: cellularOnline
    },
    meta: {
        timestamp: new Date().toISOString(),
        flow_version: global.get("flowVersion") || null,
    }
};


return msg;

// Semtech UDP protocol (packet forwarder -> 127.0.0.1:1702)
// byte 0 version, 1-2 token, 3 identifier, PUSH_DATA: 4-11 gateway EUI, 12.. JSON
const buf = msg.payload;
if (!Buffer.isBuffer(buf) || buf.length < 4) return null;
const ver = buf[0], t1 = buf[1], t2 = buf[2], ident = buf[3];
const reply = { ip: msg.ip, port: msg.port };

if (ident === 0x02) {                      // PULL_DATA -> PULL_ACK (keeps the destination "connected")
    reply.payload = Buffer.from([ver, t1, t2, 0x04]);
    return [reply, null];
}
if (ident !== 0x00 || buf.length < 13) return null;   // only PUSH_DATA carries data

reply.payload = Buffer.from([ver, t1, t2, 0x01]);   // PUSH_ACK
const text = buf.slice(12).toString("utf8");
let data;
try { data = JSON.parse(text); } catch (e) {
    node.warn("PUSH_DATA ohne gueltiges JSON");
    return [reply, null];
}
const now = Date.now();
const st = flow.get("udpStats") || { push_data: 0, rxpk: 0, stat: 0 };
st.push_data++;
flow.set("lastUdpPacket", now);
if (data.stat) {
    st.stat++; flow.set("lastStatReceived", now);
    // radio window: packet forwarder statistics (every 30 s), last 30 min
    const s = data.stat, win = (flow.get("statWindow") || []).filter(x => now - x.ts < 30 * 60 * 1000);
    win.push({ ts: now, rxnb: s.rxnb || 0, rxok: s.rxok || 0, rxfw: s.rxfw || 0, ackr: s.ackr, dwnb: s.dwnb || 0, txnb: s.txnb || 0 });
    flow.set("statWindow", win);
}
if (Array.isArray(data.rxpk) && data.rxpk.length) {
    st.rxpk += data.rxpk.length; flow.set("lastRxpk", now);
    // signal of received packets (rssi/lsnr), last 30 min
    const sig = (flow.get("sigWindow") || []).filter(x => now - x.ts < 30 * 60 * 1000);
    const devs = flow.get("devices") || {};
    data.rxpk.forEach(p => {
        if (p.stat !== 1 || typeof p.rssi !== "number") return;
        const sf = /SF(\d+)/.exec(p.datr || "");
        sig.push({ ts: now, rssi: p.rssi, lsnr: p.lsnr, freq: p.freq, sf: sf ? +sf[1] : null });
        // sensor identity from the LoRaWAN header: DevAddr (data uplink) or DevEUI (join request)
        let b; try { b = Buffer.from(p.data || "", "base64"); } catch (e) { return; }
        const mtype = b.length ? b[0] >> 5 : -1;
        let id = null, kind = null, fcnt = null;
        if ((mtype === 2 || mtype === 4) && b.length >= 8) {
            id = Buffer.from(b.slice(1, 5)).reverse().toString("hex").toUpperCase(); kind = "devaddr"; fcnt = b[6] | (b[7] << 8);
        } else if (mtype === 0 && b.length >= 17) {
            id = Buffer.from(b.slice(9, 17)).reverse().toString("hex").toUpperCase(); kind = "join";
        }
        if (!id) return;
        const d = devs[id] || { kind: kind, count: 0, first: now };
        d.count++; d.last = now; d.rssi = p.rssi; d.snr = p.lsnr; d.sf = sf ? +sf[1] : null; d.freq = p.freq;
        if (fcnt !== null) d.fcnt = fcnt;
        devs[id] = d;
    });
    // keep 24 h, at most 500 sensors
    const keep = Object.entries(devs).filter(([, d]) => now - d.last < 24 * 3600 * 1000)
        .sort((a, b) => b[1].last - a[1].last).slice(0, 500);
    flow.set("devices", Object.fromEntries(keep));
    flow.set("sigWindow", sig.slice(-2000));
}
flow.set("udpStats", st);
flow.set("gatewayEuiUdp", buf.slice(4, 12).toString("hex").toUpperCase());
node.status({ fill: "green", shape: "dot", text: `rxpk ${st.rxpk} / stat ${st.stat}` });

// same shape as before: payload is the Semtech JSON as text (db monitor app parses it unchanged)
return [reply, { payload: text, data: data }];

const now = Date.now();
const age = k => { const t = flow.get(k); return t ? Math.round((now - t) / 1000) : null; };
const st = flow.get("udpStats") || { push_data: 0, rxpk: 0, stat: 0 };
const statAge = age("lastStatReceived");
msg.statusCode = (statAge !== null && statAge < 65) ? 200 : 503;
msg.headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
msg.payload = {
    source: "udp:1702",
    flow_version: global.get("flowVersion") || null,
    gateway_eui: flow.get("gatewayEuiUdp") || null,
    seconds_since_packet: age("lastUdpPacket"),
    seconds_since_stat: statAge,
    seconds_since_rxpk: age("lastRxpk"),
    counts: st,
    app: (() => {
        const p = global.get("appPoll");
        return {
            seconds_since_poll: p ? Math.round((now - p.ts) / 1000) : null,
            last_poll: p ? new Date(p.ts).toISOString() : null,
            client: p ? p.client : null,
            agent: p ? p.agent : null,
            polls: global.get("appPollCount") || 0
        };
    })(),
    meta: global.get("gatewayMetaString") || null,
    devices: Object.entries(flow.get("devices") || {}).map(([id, d]) => ({
        id: id, kind: d.kind, count: d.count, seconds_since: Math.round((now - d.last) / 1000),
        rssi: d.rssi, snr: d.snr, sf: d.sf, freq: d.freq, fcnt: d.fcnt === undefined ? null : d.fcnt
    })),
    radio: (() => {
        // last 30 min: crc = packets received with a bad CRC (interference, collisions, antenna)
        const w = flow.get("statWindow") || [], sig = flow.get("sigWindow") || [];
        const sum = k => w.reduce((a, x) => a + (x[k] || 0), 0);
        const rxnb = sum("rxnb"), rxok = sum("rxok");
        const acks = w.map(x => x.ackr).filter(v => typeof v === "number");
        const avg = (a, k) => a.length ? Math.round(a.reduce((s, x) => s + x[k], 0) / a.length * 10) / 10 : null;
        return {
            window_minutes: 30, stats: w.length,
            rx_total: rxnb, rx_ok: rxok, rx_forwarded: sum("rxfw"),
            crc_error_pct: rxnb ? Math.round((rxnb - rxok) / rxnb * 1000) / 10 : null,
            tx_requested: sum("dwnb"), tx_sent: sum("txnb"),
            ack_pct: acks.length ? Math.round(acks.reduce((a, v) => a + v, 0) / acks.length * 10) / 10 : null,
            packets: sig.length, rssi_avg: avg(sig, "rssi"), snr_avg: avg(sig, "lsnr"),
            rssi_min: sig.length ? Math.min(...sig.map(x => x.rssi)) : null,
            // downlinks the forwarder could not send (too late/early, collision, duty cycle); reason only reaches the LNS
            tx_failed: Math.max(0, sum("dwnb") - sum("txnb")),
            sf: sig.reduce((a, x) => { if (x.sf) a["SF" + x.sf] = (a["SF" + x.sf] || 0) + 1; return a; }, {})
        };
    })()
};
return msg;

// Push to the GatewayChef cloud (flow >= 1.4.0): "start" once after Node-RED starts, then "beat" every minute.
// Exec output: line 1 /proc/uptime, then ifconfig wg0 ("inet addr:172.30.x.y").
const out = String(msg.payload || "");
const up = parseFloat(out.split(/\s+/)[0]);
const ipm = /inet addr:(172\.30\.\d+\.\d+)/.exec(out);
const now = Date.now();
const w = (flow.get("statWindow") || []).filter(x => now - x.ts < 5 * 60 * 1000);
const sig = (flow.get("sigWindow") || []).filter(x => now - x.ts < 5 * 60 * 1000);
const sum = k => w.reduce((a, x) => a + (x[k] || 0), 0);
const rxnb = sum("rxnb"), rxok = sum("rxok");
const st = flow.get("udpStats") || { rxpk: 0 };
const last = flow.get("lastRxpk");
const sf = sig.reduce((a, x) => { if (x.sf) a["SF" + x.sf] = (a["SF" + x.sf] || 0) + 1; return a; }, {});
msg.payload = {
    kind: msg.topic === "start" ? "start" : "beat",
    eui: flow.get("gatewayEuiUdp") || null,
    vpn_ip: ipm ? ipm[1] : null,
    flow_version: global.get("flowVersion") || null,
    uptime_s: isNaN(up) ? null : Math.round(up),
    rx_total: rxnb, rx_ok: rxok,
    crc_error_pct: rxnb ? Math.round((rxnb - rxok) / rxnb * 1000) / 10 : null,
    tx_failed: Math.max(0, sum("dwnb") - sum("txnb")),
    rxpk: st.rxpk,
    seconds_since_rxpk: last ? Math.round((now - last) / 1000) : null,
    sensors: Object.keys(flow.get("devices") || {}).length,
    sf: sf
};
if (!msg.payload.eui && !msg.payload.vpn_ip) { node.status({ fill: "yellow", shape: "ring", text: "noch keine EUI/VPN-IP" }); return null; }
msg.method = "POST";
msg.headers = { "Content-Type": "application/json", "X-GW-Report-Token": "{{gw_report_token}}" };
node.status({ fill: "blue", shape: "dot", text: msg.payload.kind + " " + new Date(now).toISOString().slice(11, 16) });
return msg;
